import { useState, useEffect } from "react";
import axios from "axios";

function RegisterPage() {

    const [name, setName] =
        useState("");

    const [email, setEmail] =
        useState("");

    const [password, setPassword] =
        useState("");

    const [phone, setPhone] =
        useState("");

    const [otp, setOtp] =
        useState("");

    const [otpSent, setOtpSent] =
        useState(false);

    const [otpVerified, setOtpVerified] =
        useState(false);

    const [countdown, setCountdown] =
        useState(0);

    useEffect(() => {

        let timer;

        if (countdown > 0) {

            timer = setTimeout(() => {

                setCountdown(countdown - 1);

            }, 1000);

        }

        return () => clearTimeout(timer);

    }, [countdown]);

    const sendOtp = () => {

        if (!name) {

            alert("Enter Name");

            return;
        }

        if (!email) {

            alert("Enter Email");

            return;
        }

        if (!password) {

            alert("Enter Password");

            return;
        }

        if (!phone) {

            alert("Enter Phone");

            return;
        }

        axios

            .post(

                "http://localhost:8081/customer/send-registration-otp",

                {

                    email: email

                }

            )

            .then((response) => {

                alert(response.data);

                if (response.data === "OTP Sent Successfully") {

                    setOtpSent(true);

                    setCountdown(60);

                }

            })

            .catch(() => {

                alert("Unable To Send OTP");

            });

    };

    const verifyOtp = () => {

        if (!otp) {

            alert("Enter OTP");

            return;

        }

        axios

            .post(

                "http://localhost:8081/customer/verify-registration-otp",

                {

                    email: email,

                    otp: otp

                }

            )

            .then((response) => {

                alert(response.data);

                if (response.data === "OTP Verified") {

                    setOtpVerified(true);

                }

            })

            .catch(() => {

                alert("OTP Verification Failed");

            });

    };

    const registerCustomer = () => {

        if (!otpVerified) {

            alert("Please Verify OTP First");

            return;

        }

        axios

            .post(

                "http://localhost:8081/customer/register-with-otp",

                {

                    name: name,

                    email: email,

                    password: password,

                    phone: phone,

                    otp: otp

                }

            )

            .then((response) => {

                alert(response.data);

                if (response.data === "Registration Successful") {

                    window.location.href = "/login";

                }

            })

            .catch(() => {

                alert("Registration Failed");

            });

    };

    return (

        <div

            style={{

                width: "450px",

                margin: "40px auto",

                padding: "30px",

                borderRadius: "10px",

                boxShadow: "0px 0px 10px lightgray",

                backgroundColor: "white"

            }}

        >

            <h2

                style={{

                    textAlign: "center"

                }}

            >

                Customer Registration

            </h2>

            <br />

            <input

                type="text"

                placeholder="Name"

                value={name}

                onChange={(e) =>
                    setName(e.target.value)
                }

                style={{

                    width: "100%",

                    padding: "12px",

                    marginBottom: "15px"

                }}

            />

            <input

                type="email"

                placeholder="Email"

                value={email}

                onChange={(e) =>
                    setEmail(e.target.value)
                }

                style={{

                    width: "100%",

                    padding: "12px",

                    marginBottom: "15px"

                }}

            />

            <input

                type="password"

                placeholder="Password"

                value={password}

                onChange={(e) =>
                    setPassword(e.target.value)
                }

                style={{

                    width: "100%",

                    padding: "12px",

                    marginBottom: "15px"

                }}

            />

            <input

                type="text"

                placeholder="Phone Number"

                value={phone}

                onChange={(e) =>
                    setPhone(e.target.value)
                }

                style={{

                    width: "100%",

                    padding: "12px",

                    marginBottom: "20px"

                }}

            />
                        {

                !otpSent &&

                <button

                    onClick={sendOtp}

                    style={{

                        width: "100%",

                        padding: "12px",

                        backgroundColor: "#2196F3",

                        color: "white",

                        border: "none",

                        borderRadius: "5px",

                        cursor: "pointer",

                        marginBottom: "20px"

                    }}

                >

                    Send OTP

                </button>

            }

            {

                otpSent &&

                <>

                    <input

                        type="text"

                        placeholder="Enter OTP"

                        value={otp}

                        onChange={(e) =>
                            setOtp(e.target.value)
                        }

                        style={{

                            width: "100%",

                            padding: "12px",

                            marginBottom: "15px"

                        }}

                    />

                    {

                        !otpVerified &&

                        <button

                            onClick={verifyOtp}

                            style={{

                                width: "100%",

                                padding: "12px",

                                backgroundColor: "#4CAF50",

                                color: "white",

                                border: "none",

                                borderRadius: "5px",

                                cursor: "pointer",

                                marginBottom: "15px"

                            }}

                        >

                            Verify OTP

                        </button>

                    }

                    {

                        otpVerified &&

                        <div

                            style={{

                                color: "green",

                                fontWeight: "bold",

                                textAlign: "center",

                                marginBottom: "15px"

                            }}

                        >

                            ✅ OTP Verified Successfully

                        </div>

                    }

                    {

                        !otpVerified &&

                        <div

                            style={{

                                textAlign: "center",

                                marginBottom: "15px"

                            }}

                        >

                            {

                                countdown > 0 ?

                                    <span>

                                        Resend OTP in {countdown} sec

                                    </span>

                                    :

                                    <button

                                        onClick={sendOtp}

                                        style={{

                                            background: "none",

                                            border: "none",

                                            color: "#1976D2",

                                            cursor: "pointer",

                                            fontWeight: "bold"

                                        }}

                                    >

                                        Resend OTP

                                    </button>

                            }

                        </div>

                    }

                </>

            }

            <button

                onClick={registerCustomer}

                disabled={!otpVerified}

                style={{

                    width: "100%",

                    padding: "12px",

                    backgroundColor:

                        otpVerified

                            ? "#000"

                            : "gray",

                    color: "white",

                    border: "none",

                    borderRadius: "5px",

                    cursor:

                        otpVerified

                            ? "pointer"

                            : "not-allowed",

                    fontSize: "16px"

                }}

            >

                Create Account

            </button>

        </div>

    );

}

export default RegisterPage;
